#include <stdio.h>

int main(void)
{
    int day, count = 0, days = 0;
    double money;

    /* 每天买前一天的 2 倍，直到不超过 100 的最大个数为止：2,4,8,16,32,64 */
    for (day = 2; day <= 100; day = day * 2) {
        count = count + day;
        days = days + 1;
    }

    money = count * 0.8;
    printf("%.2f\n", money / days);

    return 0;
}

#include <stdio.h>

int main(void)
{
    int i, m;

    for (i = 1; i <= 99; i++) {
        /* 一位数看平方后的末 1 位，两位数看末 2 位 */
        if (i < 10)
            m = 10;
        else
            m = 100;
        if (i * i % m == i)
            printf("%3d", i);
    }
    printf("\n");

    return 0;
}

#include <stdio.h>

int main(void)
{
    int x, y, i, r = 1;

    if (scanf("%d %d", &x, &y) != 2)
        return 1;

    /* 只保留最后 3 位：每乘一次就取模，避免溢出 */
    x = ((x % 1000) + 1000) % 1000;
    for (i = 0; i < y; i++)
        r = r * x % 1000;

    printf("%03d\n", r);

    return 0;
}

