#include <stdio.h>
int main(void)
{
    int m, i, s;
    scanf("%d", &m);
    s = 0;
    for (i = 1; i <= m; i++)
        if (m % i == 0) s += i;
    if (s = m)
        printf("%d is a perfect number\n", m);
    else
        printf("%d is not a perfect number\n", m);
    return 0;
}

