  int m,n,i,j,k,found=0,a[100][100];
  scanf("%d%d",&m,&n);
  for(i=0;i<m;i++)
    for(j=0;j<n;j++)
      scanf("%d",&a[i][j]);
  for(i=0;i<m;i++){
    for(j=0;j<n;j++){
      int maxr=1, minc=1;
      for(k=0;k<n;k++) if(a[i][k]>a[i][j]) maxr=0;
      for(k=0;k<m;k++) if(a[k][j]<a[i][j]) minc=0;
      if(maxr&&minc){ printf("%d\n", a[i][j]); found=1; }
    }
  }
  if(!found) printf("NONE\n");
  return 0;
}

